#[cfg(feature = "v26_1")]
/// Bit flags in a `u8`; unknown bits are kept as-is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
pub struct PlayerInfoAction(pub u8);
#[cfg(feature = "v26_1")]
impl PlayerInfoAction {
    /// `add_player`
    pub const ADD_PLAYER: Self = Self(1 << 0);
    /// `initialize_chat`
    pub const INITIALIZE_CHAT: Self = Self(1 << 1);
    /// `update_game_mode`
    pub const UPDATE_GAME_MODE: Self = Self(1 << 2);
    /// `update_listed`
    pub const UPDATE_LISTED: Self = Self(1 << 3);
    /// `update_latency`
    pub const UPDATE_LATENCY: Self = Self(1 << 4);
    /// `update_display_name`
    pub const UPDATE_DISPLAY_NAME: Self = Self(1 << 5);
    /// `update_hat`
    pub const UPDATE_HAT: Self = Self(1 << 6);
    /// `update_list_order`
    pub const UPDATE_LIST_ORDER: Self = Self(1 << 7);
    /// Whether every bit of `f` is set.
    #[inline]
    pub const fn contains(self, f: Self) -> bool {
        self.0 & f.0 == f.0
    }
    /// The union of both sets of bits.
    #[inline]
    #[must_use]
    pub const fn with(self, f: Self) -> Self {
        Self(self.0 | f.0)
    }
}

